/**
 * "Everything is falling apart"
 * 
 * The state of the world is gloomy. With so much going on, it's easy to feel overwhelmed. So many bad news, so much noise.
 * This is my depiction of how can it feels sometimes.
 * It's ok to disconnect from the news, take a break, and just enjoy the momentary silence.
 */

const PAGE_W = 900;
const PAGE_H = 1200;
const MARGIN = 36;
const GUTTER_W = 28;
const GUTTER_H = 10;

const FONT_HEADER = './BebasNeue-Regular.ttf';
const FONT_BODY = './LibreBaskerville-Regular.ttf';

const FUSE_CELL = 8;
const FUSE_WAYPOINTS = 5;
const FUSE_WAYPOINT_TRIES = 40;

/** Recursive splits: bomb = fine shards; other photos = coarser (see break-image.js). */
const SHATTER_DEPTH_BOMB = 8;
const SHATTER_DEPTH_OTHER = 4;
const FUSE_BURN_MS = 5000;

/** Radial blast from bomb image center: force ∝ 1/(1 + (dist/blastRadius)²). */
const EXPLOSION_BLAST_RADIUS = 400;
const EXPLOSION_WORD_PEAK = 0.04;
const EXPLOSION_SHARD_PEAK = 0.045;
/** Impulse multiplier when the body’s center is inside the bomb image rectangle. */
const EXPLOSION_CORE_BOOST = 1.55;

/** Stop when this fraction of dynamic bodies (words + shards) are sleeping — skips `Engine.update`. */
const PHYSICS_SETTLED_SLEEP_RATIO = 0.9;

let imageExploded = false;
let physicsStarted = false;
let physicsSettled = false;
let matterEngine;
let wordBodies = [];
let shardBodies = [];
let separatorBodies = [];
let wallBodies = [];

const MatterApi = typeof Matter !== 'undefined' ? Matter : null;

const STOCK_IMAGE_FILES = [ // Credits at the bottom of the file
  'pexels-alesustinau-11734706.jpg',
  'pexels-asumaani-9609066.jpg',
  'pexels-dennisariel-14117283.jpg',
  'pexels-doruk-aksel-anil-477355556-15823381.jpg',
  'pexels-eduraw-35982172.jpg',
  'pexels-huseyin-petek-467072656-15705876.jpg',
  'pexels-jani-kantokoski-2864880-25490565.jpg',
  'pexels-lord-over-makers-139936507-10537110.jpg',
  'pexels-maumascaro-4870334.jpg',
  'pexels-mitchel3uo-4614294.jpg',
  'pexels-neneqo-fotografo-574087123-17821299.jpg',
  'pexels-pixabay-76969.jpg',
  'pexels-tima-miroshnichenko-6266689.jpg',
];

/** Loaded p5.Image instances (populated in setup). */
let stockPhotoImages = [];

const grainShader = `
  precision highp float;
  varying vec2 vTexCoord;
  uniform sampler2D tex0;
  uniform float grainAmount;
  uniform float grainStrength;

  float rand(vec2 n) {
    return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
  }

  void main() {
    vec4 color = texture2D(tex0, vTexCoord);
    float noise = rand(vTexCoord * 1234.5678) * 2.0 - 1.0;
    vec3 grain = vec3(noise, noise, noise) * grainStrength * grainAmount;
    gl_FragColor = vec4(clamp(color.rgb + grain, 0.0, 1.0), color.a);
  }
`;

let grainFilter = null;

const IMG_H_MIN = 150;
const IMG_H_MAX = 420;

const BODY_TEXT_SIZE = 16;
const BODY_LEADING = 20;
const CAPTION_TEXT_SIZE = 14;
const CAPTION_LEADING = 18;

const PAPER = '#F3F1E2';
const INK = '#1A1612';
const INK_MED = '#3A3028';
const RULE = '#7A6A58';
const FUSE = '#CC5500';

/** Pack 0–255 RGB into `#RRGGBB` (sampled pixels, paper tints). */
function rgbToHex(r, g, b) {
  const h = (n) => constrain(round(n), 0, 255).toString(16).padStart(2, '0');
  return `#${h(r)}${h(g)}${h(b)}`;
}

/** Every `caption` immediately follows an `image` (footnote below photo). */
const COL_PATTERNS = [
  ['body', 'image', 'caption', 'body'],
  ['image', 'caption', 'body', 'body'],
  ['body', 'body', 'image', 'caption'],
  ['body', 'image', 'body'],
  ['image', 'caption', 'body'],
  ['body', 'image', 'caption', 'body', 'body'],
  ['body', 'body', 'image', 'caption', 'body'],
];

let layout;
let fontHeader;
let fontBody;
/** Canvas pixel size (viewport fit, same aspect as PAGE_W : PAGE_H). */
let displayW = PAGE_W;
let displayH = PAGE_H;


async function setup() {
  updateDisplaySize();
  createCanvas(displayW, displayH);
  pixelDensity(1);
  try {
    grainFilter = createFilterShader(grainShader);
    grainFilter.setUniform('grainAmount', 1.0);
    grainFilter.setUniform('grainStrength', random(0.035, 0.065));
  } catch {
    grainFilter = null;
  }
  fontHeader = await loadFont(FONT_HEADER);
  fontBody = await loadFont(FONT_BODY);
  textFont(fontBody || 'Georgia');
  await loadStockPhotos();
  layout = buildLayout();
  if (DEBUG_WORD_CACHE) {
    exportWordMetricsCache();
  }
}

function draw() {
  if (physicsStarted && MatterApi && !physicsSettled) {
    MatterApi.Engine.update(matterEngine, min(1000 / 60, 33));
    if (shouldStopPhysicsForSleepRatio()) physicsSettled = true;
  }

  background(PAPER);

  push();
  scale(displayW / PAGE_W, displayH / PAGE_H);

  const innerX = MARGIN;
  const innerY = MARGIN;
  const innerW = PAGE_W - MARGIN * 2;
  const innerH = PAGE_H - MARGIN * 2;

  noStroke();
  fill(PAPER);
  rect(innerX, innerY, innerW, innerH);
  drawPaperStains(layout.paperStains);

  let y = innerY;

  const mastH = 88;
  drawMasthead(innerX, y, innerW, mastH);
  y += mastH;

  const kickerH = 24;
  drawKicker(innerX, y, innerW, kickerH);
  y += kickerH + 6;

  const bannerH = 132;
  drawBanner(innerX, y, innerW, bannerH);
  y += bannerH + 4;

  const subH = 44;
  drawSecondary(innerX, y, innerW, subH);
  y += subH + 4;

  const divH = 14;
  if (!physicsStarted) {
    drawDivider(innerX, y, innerW, divH);
  }
  y += divH + 4;

  for (const col of layout.columns) {
    let zy = y;
    for (const z of col.zones) {
      if (z.type === 'image') {
        if (physicsStarted) {
          // shard pieces drawn as Matter bodies
        } else if (imageExploded && z.shards) {
          drawImageShards(z.shards);
        } else {
          drawStockPhotoInSlot(z);
        }
      }
      zy += z.h + GUTTER_H;
    }
  }

  if (!physicsStarted) {
    drawStaticWords(layout.words);
  } else {
    drawShardBodies();
    drawSeparatorBodies();
    drawWordBodies();
  }

  if (DEBUG_BOUNDS) drawDebugBounds(layout, y);

  const burnT = constrain(millis() / FUSE_BURN_MS, 0, 1);
  if (burnT >= 1 && !imageExploded) imageExploded = true;
  if (imageExploded && !physicsStarted && layout.bombCenter && MatterApi) {
    initWordPhysics();
  }
  if (!imageExploded) {
    drawFusePath(layout.fusePath, burnT, false);
  }

  pop();

  if (grainFilter) {
    filter(grainFilter);
  }
}

// ── Drawing ──────────────────────────────────────────────────────────────

function drawStockPhotoInSlot(z) {
  const s = z.stockSlot;
  if (!s) {
    return;
  }
  if (!z.stockImg || !z.stockCrop) {
    drawImageRect({ x: s.x, y: s.y, w: s.w, h: s.h });
    return;
  }
  image(z.stockImg, s.x, s.y, s.w, s.h, z.stockCrop.sx, z.stockCrop.sy, z.stockCrop.sw, z.stockCrop.sh);
  noFill();
  stroke(INK);
  strokeWeight(2);
  rect(s.x, s.y, s.w, s.h);
  strokeWeight(1);
  stroke(INK_MED);
  rect(s.x + 4, s.y + 4, s.w - 8, s.h - 8);
  noStroke();
}

function drawPaperStains(stains) {
  if (!stains || !stains.length) return;
  noStroke();
  for (const s of stains) {
    const col = color(s.c);
    col.setAlpha(s.a * 255);
    fill(col);
    circle(s.x, s.y, s.d);
  }
}

function drawImageShards(shards) {
  if (!shards || !shards.length) return;
  for (const s of shards) {
    fill(s.c);
    stroke(INK_MED);
    strokeWeight(0.5);
    beginShape();
    for (const [vx, vy] of s.verts) {
      vertex(vx, vy);
    }
    endShape(CLOSE);
  }
  noStroke();
}

function drawStaticWords(words) {
  if (!words) return;
  for (const W of words) {
    if (!W.text) continue;
    push();
    textFont(W.fontKind === 'header' ? fontHeader : fontBody);
    textSize(W.size);
    textStyle(W.italic ? ITALIC : NORMAL);
    textAlign(LEFT, TOP);
    fill(W.fill);
    text(W.text, W.x, W.y);
    pop();
  }
}

function drawShardBodies() {
  if (!shardBodies || !shardBodies.length) return;
  for (const b of shardBodies) {
    const hex = b.shardColor;
    if (!hex) continue;
    fill(hex);
    stroke(INK_MED);
    strokeWeight(0.5);
    const parts = b.parts && b.parts.length ? b.parts : [b];
    for (const part of parts) {
      if (!part.vertices || part.vertices.length < 3) continue;
      beginShape();
      for (const v of part.vertices) {
        vertex(v.x, v.y);
      }
      endShape(CLOSE);
    }
  }
  noStroke();
}

function drawSeparatorBodies() {
  if (!separatorBodies || !separatorBodies.length) return;
  for (const b of separatorBodies) {
    const s = b.sep;
    if (!s) continue;
    push();
    translate(b.position.x, b.position.y);
    rotate(b.angle);
    noStroke();
    fill(RULE);
    rectMode(CENTER);
    rect(0, 0, s.w, s.h);
    rectMode(CORNER);
    pop();
  }
}

function drawWordBodies() {
  for (const b of wordBodies) {
    const W = b.wd;
    if (!W || !W.text) continue;
    push();
    translate(b.position.x, b.position.y);
    rotate(b.angle);
    textFont(W.fontKind === 'header' ? fontHeader : fontBody);
    textSize(W.size);
    textStyle(W.italic ? ITALIC : NORMAL);
    textAlign(CENTER, CENTER);
    fill(W.fill);
    text(W.text, 0, 0);
    pop();
  }
}

function drawDebugBounds(layout, colAreaDrawY) {
  push();
  noFill();
  strokeWeight(1);

  stroke(DEBUG_STROKE_ZONE);
  for (const hz of layout.headerZones) {
    rect(hz.x, hz.y, hz.w, hz.h);
  }

  for (const col of layout.columns) {
    let zy = colAreaDrawY;
    for (const z of col.zones) {
      if (z.type === 'image') stroke(DEBUG_STROKE_IMAGE);
      else if (z.type === 'caption') stroke(DEBUG_STROKE_CAPTION);
      else stroke(DEBUG_STROKE_ZONE);
      rect(col.x, zy, col.w, z.h);
      zy += z.h + GUTTER_H;
    }
  }

  pop();
}

function drawMasthead(x, y, w, h) {}

function drawKicker(x, y, w, h) {}

function drawBanner(x, y, w, h) {}

function drawSecondary(x, y, w, h) {}

function drawDivider(x, y, w, h) {
  stroke(RULE);
  strokeWeight(3);
  line(x, y + h / 2, x + w * 0.22, y + h / 2);
  line(x + w * 0.78, y + h / 2, x + w, y + h / 2);
  strokeWeight(1);
  line(x + w * 0.24, y + h / 2, x + w * 0.76, y + h / 2);
  noStroke();
}

function drawBodyBlock(x, y, w, h, bodyText) {}

function drawCaption(x, y, w, h, line) {}

function drawImageRect(r) {
  noFill();
  stroke(INK);
  strokeWeight(2);
  rect(r.x, r.y, r.w, r.h);
  strokeWeight(1);
  stroke(INK_MED);
  rect(r.x + 4, r.y + 4, r.w - 8, r.h - 8);
  noStroke();
}

function drawFuseSpark(cx, cy) {
  push();
  translate(cx, cy);
  strokeCap(ROUND);
  let nRed = 10 + floor(random(10));
  let nYellow = 20 + floor(random(10));

  for (let i = 0; i < nYellow + nRed; i++) {
    const a = random(TWO_PI);
    const c = cos(a);
    const s = sin(a);
    const r0 = random(5, 10);
    const r1 = r0 + random(10, 20);
    stroke(i < nYellow ? '#FFFF00' : '#FF0000');
    strokeWeight(random(0.2, 0.5));
    line(c * r0, s * r0, c * r1, s * r1);
  }

  pop();
}

function drawFusePath(pts, burnProgress, burnComplete) {
  if (!pts || pts.length < 2) return;
  const totalLen = polylineLength(pts);
  const dist = burnComplete ? totalLen : burnProgress * totalLen;
  const { pts: partial, tip } = fusePolylineUpTo(pts, dist);

  stroke(FUSE);
  strokeWeight(3);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  noFill();
  beginShape();
  for (const [px, py] of partial) {
    vertex(px, py);
  }
  endShape();

  const end = tip || pts[pts.length - 1];
  if (!burnComplete && burnProgress > 0) {
    drawFuseSpark(end[0], end[1]);
  }
  fill(FUSE);
  noStroke();
  circle(end[0], end[1], burnComplete ? 6 : 8);
  noStroke();
}
// ── Utilities (layout, assets, text measure, physics, fuse routing) ─────────

function windowResized() {
  updateDisplaySize();
  resizeCanvas(displayW, displayH);
}

function updateDisplaySize() {
  const aspect = PAGE_W / PAGE_H;
  let ch = windowHeight;
  let cw = ch * aspect;
  if (cw > windowWidth) {
    cw = windowWidth;
    ch = cw / aspect;
  }
  displayW = cw;
  displayH = ch;
}

async function loadStockPhotos() {
  stockPhotoImages = [];
  for (const name of STOCK_IMAGE_FILES) {
    try {
      const img = await loadImage(`${name}`);
      if (img && img.width > 0) stockPhotoImages.push(img);
    } catch {
      console.warn('Stock image failed to load:', name);
    }
  }
  if (stockPhotoImages.length === 0) {
    console.warn('No stock images loaded; image slots use wireframe placeholders.');
  }
}

/** Center-crop source rect so aspect matches boxW/boxH (object-fit: cover). */
function computeCoverCrop(img, boxW, boxH) {
  const iw = img.width;
  const ih = img.height;
  const R = boxW / max(boxH, 1e-6);
  const r = iw / max(ih, 1e-6);
  if (r > R) {
    const sh = ih;
    const sw = ih * R;
    const sx = (iw - sw) / 2;
    return { sx, sy: 0, sw, sh };
  }
  const sw = iw;
  const sh = iw / R;
  const sy = (ih - sh) / 2;
  return { sx: 0, sy, sw, sh };
}

/** Map layout point (px,py) onto image bitmap using slot + crop; clamps to slot then samples. */
function sampleStockAtLayoutPoint(img, slot, crop, px, py) {
  const bx = slot.x;
  const by = slot.y;
  const bw = slot.w;
  const bh = slot.h;
  const qx = constrain(px, bx, bx + bw);
  const qy = constrain(py, by, by + bh);
  const u = (qx - bx) / max(bw, 1e-6);
  const v = (qy - by) / max(bh, 1e-6);
  const ix = floor(crop.sx + u * crop.sw);
  const iy = floor(crop.sy + v * crop.sh);
  const iix = constrain(ix, 0, img.width - 1);
  const iiy = constrain(iy, 0, img.height - 1);
  const col = img.get(iix, iiy);
  let r;
  let g;
  let b;
  if (Array.isArray(col)) {
    r = col[0];
    g = col[1];
    b = col[2];
  } else {
    r = red(col);
    g = green(col);
    b = blue(col);
  }
  return rgbToHex(r, g, b);
}

function shardColorForPiece(zone, piece) {
  if (!zone.stockImg || !zone.stockCrop || !zone.stockSlot) return shardPaperHex();
  let sx = 0;
  let sy = 0;
  for (const [vx, vy] of piece.verts) {
    sx += vx;
    sy += vy;
  }
  sx /= piece.verts.length;
  sy /= piece.verts.length;
  return sampleStockAtLayoutPoint(zone.stockImg, zone.stockSlot, zone.stockCrop, sx, sy);
}

function buildPaperStains(innerX, innerY, innerW, innerH) {
  const n = 20 + floor(random(18));
  const stains = [];
  for (let i = 0; i < n; i++) {
    const roll = random(1);
    const c = roll < 0.5 ? '#28221E' : roll < 0.82 ? '#694E3A' : '#484052';
    stains.push({
      x: random(innerX + 4, innerX + innerW - 4),
      y: random(innerY + 4, innerY + innerH - 4),
      d: random(10, 40),
      c,
      a: random(0.005, 0.035),
    });
  }
  return stains;
}

function shouldStopPhysicsForSleepRatio() {
  const dynamics = wordBodies.concat(shardBodies).concat(separatorBodies);
  const n = dynamics.length;
  if (n === 0) return true;
  let asleep = 0;
  for (let i = 0; i < n; i++) {
    if (dynamics[i].isSleeping) asleep++;
  }
  return asleep / n >= PHYSICS_SETTLED_SLEEP_RATIO;
}

function shardPaperHex() {
  return rgbToHex(
    237 + random(-14, 14),
    232 + random(-14, 14),
    208 + random(-10, 10)
  );
}

function measureChar(ch, font, size, italic) {
  textFont(font || fontBody);
  textSize(size);
  textStyle(italic ? ITALIC : NORMAL);
  textAlign(LEFT, TOP);
  /** `textBounds` often has ~0 width for space; we need real horizontal advance. */
  if (ch === ' ' || ch === '\t' || ch === '\u00a0') {
    const w =
      ch === '\t'
        ? max(textWidth('    '), size * 1.6)
        : max(textWidth(ch), size * 0.35);
    return { w, h: size * 1.05 };
  }
  if (font && typeof font.textBounds === 'function') {
    const b = font.textBounds(ch, 0, 0, size);
    return { w: max(b.w, 0.25), h: max(b.h, size * 0.75) };
  }
  textStyle(italic ? ITALIC : NORMAL);
  return { w: max(textWidth(ch), 0.25), h: size * 1.05 };
}

function layoutCenteredLineLetters(str, cx, topY, font, size, italic, fillColor, fontKind) {
  const chars = Array.from(str);
  const dims = chars.map((ch) => measureChar(ch, font, size, italic));
  const totalW = dims.reduce((s, d) => s + d.w, 0);
  let x = cx - totalW / 2;
  const lineKey = `ctr:${cx.toFixed(2)}@${topY.toFixed(2)}`;
  return chars.map((ch, i) => {
    const d = dims[i];
    const L = {
      ch,
      x,
      y: topY,
      w: d.w,
      h: max(d.h, size * 1.12),
      size,
      italic,
      fill: fillColor,
      fontKind,
      lineKey,
    };
    x += d.w;
    return L;
  });
}

function layoutWrappedTextLetters(
  paragraph,
  x,
  y,
  maxW,
  size,
  leading,
  italic,
  fillColor,
  fontAlias,
  font,
  fontKindOverride
) {
  const lines = wrapParagraphToLines(paragraph, maxW, fontAlias, size, font);
  const fk = fontKindOverride || (fontAlias === 'header' ? 'header' : 'body');
  const letters = [];
  let py = y;
  for (const line of lines) {
    const lineKey = `ln:${x.toFixed(2)}@${py.toFixed(2)}`;
    let px = x;
    for (const ch of Array.from(line)) {
      const { w, h } = measureChar(ch, font, size, italic);
      letters.push({
        ch,
        x: px,
        y: py,
        w: max(w, 0.25),
        h: max(h, size * 1.12),
        size,
        italic,
        fill: fillColor,
        fontKind: fk,
        lineKey,
      });
      px += w;
    }
    py += leading;
  }
  return letters;
}

function buildAllLetters(innerX, innerY, innerW, colAreaY, columns, headerCopy) {
  const { mastTitle, mastSub, kicker, banner, secondary } = headerCopy;
  const letters = [];
  let y = innerY;
  const mastH = 88;
  letters.push(
    ...layoutCenteredLineLetters(
      mastTitle,
      innerX + innerW / 2,
      y + mastH * 0.34,
      fontHeader,
      40,
      false,
      INK,
      'header'
    )
  );
  letters.push(
    ...layoutCenteredLineLetters(
      mastSub,
      innerX + innerW / 2,
      y + mastH * 0.72,
      fontBody,
      11,
      false,
      INK_MED,
      'body'
    )
  );
  y += mastH;
  const kickerH = 24;
  letters.push(
    ...layoutWrappedTextLetters(
      kicker,
      innerX,
      y + 4,
      innerW,
      12,
      14,
      true,
      INK_MED,
      'body',
      fontBody,
      'body'
    )
  );
  y += kickerH + 6;
  const bannerH = 132;
  letters.push(
    ...layoutWrappedTextLetters(
      banner,
      innerX + 2,
      y + 4,
      innerW - 4,
      48,
      46,
      false,
      INK,
      'header',
      fontHeader,
      'header'
    )
  );
  y += bannerH + 4;
  letters.push(
    ...layoutWrappedTextLetters(
      secondary,
      innerX,
      y + 4,
      innerW,
      17,
      22,
      false,
      INK_MED,
      'body',
      fontBody,
      'body'
    )
  );

  for (const col of columns) {
    let zy = colAreaY;
    for (const z of col.zones) {
      if (z.type === 'body') {
        letters.push(
          ...layoutWrappedTextLetters(
            z.text,
            col.x,
            zy,
            col.w,
            BODY_TEXT_SIZE,
            BODY_LEADING,
            false,
            INK,
            'body',
            fontBody,
            'body'
          )
        );
      } else if (z.type === 'caption') {
        letters.push(
          ...layoutWrappedTextLetters(
            z.text,
            col.x,
            zy,
            col.w,
            CAPTION_TEXT_SIZE,
            CAPTION_LEADING,
            true,
            INK_MED,
            'body',
            fontBody,
            'body'
          )
        );
      }
      zy += z.h + GUTTER_H;
    }
  }

  return letters;
}

/** One entry per word for physics (fewer Matter bodies than per-glyph). */
function lettersToWords(letters) {
  const words = [];
  if (!letters || !letters.length) return words;

  let run = null;
  let prevY = null;

  function flush() {
    if (!run || !run.glyphs.length) {
      run = null;
      return;
    }
    const gs = run.glyphs;
    let minX = Infinity;
    let minY = Infinity;
    let maxR = -Infinity;
    let maxB = -Infinity;
    for (const g of gs) {
      minX = Math.min(minX, g.x);
      minY = Math.min(minY, g.y);
      maxR = Math.max(maxR, g.x + g.w);
      maxB = Math.max(maxB, g.y + g.h);
    }
    const first = gs[0];
    words.push({
      text: gs.map((g) => g.ch).join(''),
      x: minX,
      y: minY,
      w: maxR - minX,
      h: maxB - minY,
      size: first.size,
      italic: first.italic,
      fill: first.fill,
      fontKind: first.fontKind,
      lineKey: first.lineKey || `f:${minY.toFixed(2)}@${minX.toFixed(2)}`,
    });
    run = null;
  }

  for (const L of letters) {
    if (L.ch === ' ' || L.ch === '\t') {
      flush();
      prevY = L.y;
      continue;
    }
    if (run && prevY !== null && L.y !== prevY) flush();
    if (!run) run = { glyphs: [] };
    run.glyphs.push(L);
    prevY = L.y;
  }
  flush();
  return words;
}

function prepareWordFont(W) {
  textFont(W.fontKind === 'header' ? fontHeader : fontBody);
  textSize(W.size);
  textStyle(W.italic ? ITALIC : NORMAL);
  textAlign(LEFT, TOP);
}

function wordSpaceWidth(W) {
  prepareWordFont(W);
  return max(textWidth(' '), W.size * 0.35);
}

function wordMeasuredDrawWidth(W) {
  prepareWordFont(W);
  return max(textWidth(W.text), 1);
}

/**
 * Glyph-run x positions ignore kerning; kerned `text()` can be wider so the next word
 * overlaps. Re-space each line/column strip using measured word + space widths.
 */
function applyWordSpacingFromKerning(words, innerX, innerW) {
  if (!words || !words.length) return;

  const pageCx = innerX + innerW / 2;
  const byLineKey = new Map();
  for (const w of words) {
    const k = w.lineKey;
    if (!byLineKey.has(k)) byLineKey.set(k, []);
    byLineKey.get(k).push(w);
  }

  for (const seg of byLineKey.values()) {
    if (!seg.length) continue;
    seg.sort((a, b) => a.x - b.x);

    const first = seg[0];

    let total = 0;
    for (let i = 0; i < seg.length; i++) {
      if (i > 0) total += wordSpaceWidth(seg[i]);
      total += wordMeasuredDrawWidth(seg[i]);
    }

    const centered =
      typeof first.lineKey === 'string' && first.lineKey.startsWith('ctr:');
    let x = centered ? pageCx - total / 2 : first.x;

    for (let i = 0; i < seg.length; i++) {
      const w = seg[i];
      w.x = x;
      prepareWordFont(w);
      w.w = max(textWidth(w.text), 3);
      w.h = max(w.h, w.size * 1.15);
      x += w.w;
      if (i < seg.length - 1) x += wordSpaceWidth(seg[i + 1]);
    }
  }
}

/**
 * Outward impulse from the bomb epicenter; stronger nearby (explosion falloff).
 * Returns falloff 0..1 for optional spin scaling.
 */
function applyExplosionForce(body, epicenterX, epicenterY, blastRadius, peak, Body, fuseRect) {
  const dx = body.position.x - epicenterX;
  const dy = body.position.y - epicenterY;
  const dist = Math.hypot(dx, dy);
  const d = max(dist, 5);
  const ux = d > 0.5 ? dx / d : random(-0.25, 0.25);
  const uy = d > 0.5 ? dy / d : random(-0.25, 0.25);
  const t = d / max(blastRadius, 40);
  const falloff = 1 / (1 + t * t);
  let mag = peak * falloff * body.mass;
  if (
    fuseRect &&
    fuseRect.w > 0 &&
    body.position.x >= fuseRect.x &&
    body.position.x <= fuseRect.x + fuseRect.w &&
    body.position.y >= fuseRect.y &&
    body.position.y <= fuseRect.y + fuseRect.h
  ) {
    mag *= EXPLOSION_CORE_BOOST;
  }
  const lift = 0.00028 * falloff * body.mass;
  Body.applyForce(body, body.position, {
    x: ux * mag,
    y: uy * mag - lift,
  });
  return falloff;
}

function matterShardBodyFromVerts(vertsArr, shardHex) {
  const { Bodies } = MatterApi;
  const pts = vertsArr.map(([vx, vy]) => ({ x: vx, y: vy }));
  let cx = 0;
  let cy = 0;
  for (const p of pts) {
    cx += p.x;
    cy += p.y;
  }
  cx /= pts.length;
  cy /= pts.length;
  const local = pts.map((p) => ({ x: p.x - cx, y: p.y - cy }));
  const body = Bodies.fromVertices(
    cx,
    cy,
    [local],
    {
      frictionAir: 0.02,
      friction: 0.55,
      restitution: 0.1,
      density: 0.0014,
    },
    true
  );
  body.shardColor = shardHex;
  return body;
}

function initWordPhysics() {
  if (!MatterApi || physicsStarted || !layout || !layout.words) return;
  physicsStarted = true;
  physicsSettled = false;
  const { Engine, Bodies, Composite, Body } = MatterApi;
  const ex = layout.bombCenter.x;
  const ey = layout.bombCenter.y;
  const ft = layout.fuseTarget;
  const blastR = max(EXPLOSION_BLAST_RADIUS, max(ft.w, ft.h) * 1.25);
  matterEngine = Engine.create();
  matterEngine.enableSleeping = true;
  matterEngine.world.gravity.y = 1;
  matterEngine.world.gravity.scale = 0.0011;

  const t = 55;
  wallBodies = [
    Bodies.rectangle(PAGE_W / 2, PAGE_H + t / 2, PAGE_W + t * 2, t, {
      isStatic: true,
      friction: 0.85,
    }),
    Bodies.rectangle(-t / 2, PAGE_H / 2, t, PAGE_H * 2.5, {
      isStatic: true,
      friction: 0.4,
    }),
    Bodies.rectangle(PAGE_W + t / 2, PAGE_H / 2, t, PAGE_H * 2.5, {
      isStatic: true,
      friction: 0.4,
    }),
    Bodies.rectangle(PAGE_W / 2, -t / 2, PAGE_W + t * 2, t, {
      isStatic: true,
      friction: 0.25,
    }),
  ];
  Composite.add(matterEngine.world, wallBodies);

  separatorBodies = [];
  if (layout.dividerSegments) {
    for (const seg of layout.dividerSegments) {
      const bw = max(seg.w, 4);
      const bh = max(seg.h, 2);
      const body = Bodies.rectangle(seg.cx, seg.cy, bw, bh, {
        frictionAir: 0.02,
        friction: 0.6,
        restitution: 0.06,
        density: 0.002,
      });
      body.sep = { w: seg.w, h: seg.h, thick: seg.thick };
      separatorBodies.push(body);
      Composite.add(matterEngine.world, body);
      const fo = applyExplosionForce(body, ex, ey, blastR, EXPLOSION_WORD_PEAK * 0.75, Body, ft);
      Body.setAngularVelocity(body, random(-0.15, 0.15) * (0.35 + 0.65 * fo));
    }
  }

  wordBodies = [];
  for (const W of layout.words) {
    if (!W.text) continue;
    const bw = max(W.w, 3);
    const bh = max(W.h, 3);
    const body = Bodies.rectangle(W.x + bw / 2, W.y + bh / 2, bw, bh, {
      frictionAir: 0.018,
      friction: 0.55,
      restitution: 0.12,
      density: 0.0012,
    });
    body.wd = W;
    wordBodies.push(body);
    Composite.add(matterEngine.world, body);

    const fo = applyExplosionForce(body, ex, ey, blastR, EXPLOSION_WORD_PEAK, Body, ft);
    Body.setAngularVelocity(body, random(-0.2, 0.2) * (0.35 + 0.65 * fo));
  }

  shardBodies = [];
  for (const col of layout.columns) {
    let zy = layout.colAreaY;
    for (const z of col.zones) {
      if (z.type === 'image' && z.shards) {
        for (const s of z.shards) {
          const body = matterShardBodyFromVerts(s.verts, s.c);
          Composite.add(matterEngine.world, body);
          shardBodies.push(body);
          const fo = applyExplosionForce(body, ex, ey, blastR, EXPLOSION_SHARD_PEAK, Body, ft);
          Body.setAngularVelocity(body, random(-0.28, 0.28) * (0.35 + 0.65 * fo));
        }
      }
      zy += z.h + GUTTER_H;
    }
  }
}

function buildLayout() {
  const innerX = MARGIN;
  const innerW = PAGE_W - MARGIN * 2;
  const innerY = MARGIN;
  const innerBottom = innerY + (PAGE_H - MARGIN * 2);

  const yHeader = innerY + 88 + 24 + 6 + 132 + 4 + 44 + 4 + 14 + 4;
  const colAreaY = yHeader;
  const colAreaH = innerBottom - colAreaY;

  const numCols = random() < 0.52 ? 3 : 4;
  const patterns = [];
  for (let i = 0; i < numCols; i++) {
    patterns.push(random(COL_PATTERNS));
  }
  if (!patterns.some((p) => p.includes('image'))) {
    const withImg = COL_PATTERNS.filter((p) => p.includes('image'));
    patterns[floor(random(numCols))] = random(withImg);
  }

  const colW = (innerW - (numCols - 1) * GUTTER_W) / numCols;

  const imageSlots = [];
  for (let ci = 0; ci < numCols; ci++) {
    patterns[ci].forEach((t, zi) => {
      if (t === 'image') imageSlots.push({ ci, zi });
    });
  }
  const featured = random(imageSlots);
  const fuseTarget = { x: 0, y: 0, w: colW, h: 0 };

  const stockDeck = stockPhotoImages.slice();
  shuffle(stockDeck, true);
  const stockForImageSlot = [];
  for (let s = 0; s < imageSlots.length; s++) {
    if (s < stockDeck.length) stockForImageSlot.push(stockDeck[s]);
    else if (stockPhotoImages.length) stockForImageSlot.push(random(stockPhotoImages));
    else stockForImageSlot.push(null);
  }
  let stockSlot = 0;

  const columns = [];
  for (let ci = 0; ci < numCols; ci++) {
    const pattern = patterns[ci];
    const x = innerX + ci * (colW + GUTTER_W);
    const w = colW;

    const captionTexts = {};
    for (let zi = 0; zi < pattern.length; zi++) {
      if (pattern[zi] === 'caption') captionTexts[zi] = random(IMAGE_CAPTIONS);
    }

    let heights = allocateColumnHeights(pattern, colAreaH, featured.ci === ci ? featured.zi : -1);
    heights = applyMeasuredCaptionHeights(pattern, heights, w, captionTexts);
    heights = fitColumnHeightsToBudget(pattern, heights, colAreaH);

    const zones = [];
    let zy = colAreaY;
    for (let zi = 0; zi < pattern.length; zi++) {
      const h = heights[zi];
      const type = pattern[zi];
      if (type === 'body') {
        const text = buildBodyFillText(w, h, 'body', BODY_TEXT_SIZE, fontBody, BODY_LEADING);
        zones.push({ type: 'body', h, text });
      } else if (type === 'image') {
        const isBomb = featured.ci === ci && featured.zi === zi;
        const simImg = stockForImageSlot[stockSlot++];
        const crop = simImg ? computeCoverCrop(simImg, w, h) : null;
        zones.push({
          type: 'image',
          h,
          isBomb,
          stockImg: simImg,
          stockCrop: crop,
          stockSlot: { x, y: zy, w, h },
        });
        if (isBomb) {
          fuseTarget.x = x;
          fuseTarget.y = zy;
          fuseTarget.w = w;
          fuseTarget.h = h;
        }
      } else {
        zones.push({ type: 'caption', h, text: captionTexts[zi] });
      }
      zy += h + GUTTER_H;
    }

    columns.push({ x, w, zones });
  }

  const headerZones = buildHeaderZones(innerX, innerY, innerW);
  const fusePath = computeFusePath(columns, colAreaY, fuseTarget, headerZones);

  for (const col of columns) {
    let zy = colAreaY;
    for (const z of col.zones) {
      if (z.type === 'image') {
        const dep = z.isBomb ? SHATTER_DEPTH_BOMB : SHATTER_DEPTH_OTHER;
        const raw = shatterRectangle(col.x, zy, col.w, z.h, dep);
        z.shards = raw.map((p) => ({
          verts: p.verts,
          c: shardColorForPiece(z, p),
        }));
      }
      zy += z.h + GUTTER_H;
    }
  }

  const headerCopy = pickHeaderCopy();
  const letters = buildAllLetters(innerX, innerY, innerW, colAreaY, columns, headerCopy);
  const words = lettersToWords(letters);
  applyWordSpacingFromKerning(words, innerX, innerW);
  const bombCenter = {
    x: fuseTarget.x + fuseTarget.w / 2,
    y: fuseTarget.y + fuseTarget.h / 2,
  };

  const divTopY = innerY + 88 + (24 + 6) + (132 + 4) + (44 + 4);
  const divH = 14;
  const dividerSegments = buildDividerSegments(innerX, divTopY, innerW, divH);

  const innerHPage = innerBottom - innerY;
  const paperStains = buildPaperStains(innerX, innerY, innerW, innerHPage);

  return {
    columns,
    colAreaY,
    fuseTarget,
    fusePath,
    headerZones,
    letters,
    words,
    bombCenter,
    dividerSegments,
    paperStains,
  };
}

function buildHeaderZones(innerX, innerY, innerW) {
  const zones = [];
  let y = innerY;
  const mastH = 88;
  zones.push({ x: innerX, y, w: innerW, h: mastH });
  y += mastH;
  const kickerH = 24;
  zones.push({ x: innerX, y, w: innerW, h: kickerH });
  y += kickerH + 6;
  const bannerH = 132;
  zones.push({ x: innerX, y, w: innerW, h: bannerH });
  y += bannerH + 4;
  const subH = 44;
  zones.push({ x: innerX, y, w: innerW, h: subH });
  y += subH + 4;
  const divH = 14;
  zones.push({ x: innerX, y, w: innerW, h: divH });
  return zones;
}

function columnStackHeight(pattern, heights) {
  const n = pattern.length;
  return heights.reduce((a, b) => a + b, 0) + (n - 1) * GUTTER_H;
}

/**
 * Replace caption slot heights with wrapped text height from textBounds (min 1 line).
 */
function applyMeasuredCaptionHeights(pattern, heights, colW, captionTexts) {
  const next = heights.slice();
  for (let i = 0; i < pattern.length; i++) {
    if (pattern[i] !== 'caption') continue;
    const cap = captionTexts[i] || '';
    const lines = wrapParagraphToLines(cap, colW, 'body', CAPTION_TEXT_SIZE, fontBody);
    const h = max(CAPTION_LEADING, lines.length * CAPTION_LEADING);
    next[i] = ceil(h);
  }
  return next;
}

/**
 * Ensure sum(zoneH) + gutters <= colAreaH; shrink bodies first, then trim last body; add slack to bodies if under.
 */
function fitColumnHeightsToBudget(pattern, heights, colAreaH) {
  const n = pattern.length;
  const h = heights.slice();
  let total = columnStackHeight(pattern, h);
  let overflow = total - colAreaH;

  if (overflow > 0) {
    const bodyIdx = [];
    for (let i = 0; i < n; i++) if (pattern[i] === 'body') bodyIdx.push(i);
    for (let i = bodyIdx.length - 1; i >= 0 && overflow > 0; i--) {
      const idx = bodyIdx[i];
      const take = min(overflow, max(0, h[idx] - BODY_LEADING));
      h[idx] -= take;
      overflow -= take;
    }
    if (overflow > 0) {
      for (let i = n - 1; i >= 0 && overflow > 0; i--) {
        if (pattern[i] !== 'image') continue;
        const take = min(overflow, max(0, h[i] - 72));
        h[i] -= take;
        overflow -= take;
      }
    }
    total = columnStackHeight(pattern, h);
    overflow = total - colAreaH;
    if (overflow > 0) {
      const lastBody = [...pattern.keys()].filter((i) => pattern[i] === 'body').pop();
      if (lastBody !== undefined) {
        h[lastBody] = max(BODY_LEADING, h[lastBody] - overflow);
      }
    }
  }

  total = columnStackHeight(pattern, h);
  let slack = colAreaH - total;
  if (slack > 0) {
    const bodyIdx = [];
    for (let i = 0; i < n; i++) if (pattern[i] === 'body') bodyIdx.push(i);
    if (bodyIdx.length > 0) {
      shuffle(bodyIdx, true);
      let rem = floor(slack);
      for (let k = 0; k < bodyIdx.length && rem > 0; k++) {
        const i = bodyIdx[k];
        const add = k === bodyIdx.length - 1 ? rem : floor(random(0, rem + 1));
        h[i] += add;
        rem -= add;
      }
      if (rem > 0) h[bodyIdx[bodyIdx.length - 1]] += rem;
    } else {
      const imgIdx = pattern.findIndex((t) => t === 'image');
      if (imgIdx >= 0) h[imgIdx] += floor(slack);
    }
  }

  total = columnStackHeight(pattern, h);
  slack = colAreaH - total;
  if (slack !== 0 && pattern.some((t) => t === 'body')) {
    const lastBody = [...pattern.keys()].filter((i) => pattern[i] === 'body').pop();
    h[lastBody] += slack;
    h[lastBody] = max(BODY_LEADING, h[lastBody]);
  }

  total = columnStackHeight(pattern, h);
  if (total > colAreaH && pattern.some((t) => t === 'body')) {
    const lastBody = [...pattern.keys()].filter((i) => pattern[i] === 'body').pop();
    h[lastBody] = max(BODY_LEADING, h[lastBody] - (total - colAreaH));
  }

  return h;
}

function allocateColumnHeights(pattern, colAreaH, featuredZi) {
  const n = pattern.length;
  const gutterTotal = (n - 1) * GUTTER_H;
  const usable = colAreaH - gutterTotal;

  const minCaption = () => 26 + floor(random(0, 14));
  const minBody = () => 44 + floor(random(0, 28));
  const minImageOther = () => 88 + floor(random(0, 56));

  const mins = pattern.map((t, i) => {
    if (t === 'caption') return minCaption();
    if (t === 'image') {
      if (i === featuredZi) return 72;
      return minImageOther();
    }
    return minBody();
  });

  if (featuredZi >= 0) {
    const sumOtherMins = mins.reduce((s, m, i) => (i === featuredZi ? s : s + m), 0);
    const room = usable - sumOtherMins;
    const target = random(IMG_H_MIN, IMG_H_MAX);
    const hi = min(IMG_H_MAX, max(72, room));
    const lo = min(IMG_H_MIN, hi);
    mins[featuredZi] = constrain(target, lo, hi);
  }

  let sum = mins.reduce((a, b) => a + b, 0);
  let slack = usable - sum;

  if (slack < 0) {
    const scale = usable / sum;
    for (let i = 0; i < n; i++) mins[i] = max(24, floor(mins[i] * scale));
    sum = mins.reduce((a, b) => a + b, 0);
    slack = usable - sum;
  }

  const flex = [];
  for (let i = 0; i < n; i++) {
    if (pattern[i] === 'body' || (pattern[i] === 'image' && i !== featuredZi)) flex.push(i);
  }
  if (flex.length === 0) {
    for (let i = 0; i < n; i++) if (pattern[i] === 'body') flex.push(i);
  }
  if (flex.length === 0) {
    for (let i = 0; i < n; i++) flex.push(i);
  }
  if (flex.length > 0 && slack > 0) {
    let remaining = slack;
    shuffle(flex, true);
    for (let k = 0; k < flex.length && remaining > 0; k++) {
      const i = flex[k];
      const chunk = k === flex.length - 1 ? remaining : floor(random(0, remaining + 1));
      mins[i] += chunk;
      remaining -= chunk;
    }
    if (remaining > 0) mins[flex[flex.length - 1]] += remaining;
  }

  return mins;
}

/** Whitespace-split tokens from texts.js — same grouping as word-metrics vocabulary. */
function tokenSetFromTextLines(lines) {
  const set = new Set();
  for (const line of lines) {
    for (const w of String(line).split(/\s+/)) {
      if (w) set.add(w);
    }
  }
  return set;
}

function measureWordWidthMap(sortedWords, font, refSize) {
  textFont(font || fontBody);
  textSize(refSize);
  textStyle(NORMAL);
  textAlign(LEFT, TOP);
  const words = {};
  for (const word of sortedWords) {
    let wPx;
    if (font && typeof font.textBounds === 'function') {
      wPx = font.textBounds(word, 0, 0, refSize).w;
    } else {
      wPx = textWidth(word);
    }
    words[word] = wPx;
  }
  return words;
}

/** Log copy-paste `WORD_WIDTHS` for word-metrics.js (refSize 48 header / 17 body). */
function exportWordMetricsCache() {
  if (typeof NEWSPAPER_TITLES === 'undefined') {
    console.warn('exportWordMetricsCache: texts.js not loaded');
    return;
  }
  const headerLines = [...NEWSPAPER_TITLES, ...BANNER_HEADLINES];
  const bodyLines = [
    ...SUBTEXT_LINES,
    ...KICKER_LINES,
    ...SECONDARY_HEADERS,
    ...FILLER_SENTENCES,
    ...IMAGE_CAPTIONS,
  ];
  const headerWords = [...tokenSetFromTextLines(headerLines)].sort();
  const bodyWords = [...tokenSetFromTextLines(bodyLines)].sort();
  const out = {
    header: {
      refSize: 48,
      words: measureWordWidthMap(headerWords, fontHeader, 48),
    },
    body: {
      refSize: 17,
      words: measureWordWidthMap(bodyWords, fontBody, 17),
    },
  };
  const str = `const WORD_WIDTHS = ${JSON.stringify(out, null, 2)};`;
  console.log('--- paste into word-metrics.js (replace `const WORD_WIDTHS = {};`) ---');
  console.log(str);
  console.log('--- end ---');
}

/**
 * Word width lookup — reads from the pre-computed WORD_WIDTHS cache (word-metrics.js),
 * scaled linearly to the target size. Falls back to textBounds for uncached words and
 * stores the result so each word is only ever measured once per session.
 */
const _runtimeCache = {};

function wordWidthPx(word, fontAlias, targetSize, font) {
  const cache = typeof WORD_WIDTHS !== 'undefined' ? WORD_WIDTHS : {};
  const group = cache[fontAlias];

  if (group && group.words && group.words[word] !== undefined) {
    return group.words[word] * (targetSize / group.refSize);
  }

  const rtKey = `${fontAlias}:${word}`;
  if (_runtimeCache[rtKey] !== undefined) {
    const rt = _runtimeCache[rtKey];
    return rt.w * (targetSize / rt.refSize);
  }

  const refSize = (group && group.refSize) || targetSize;
  let w;
  if (font && typeof font.textBounds === 'function') {
    textFont(font);
    textSize(refSize);
    textAlign(LEFT, TOP);
    textStyle(NORMAL);
    w = font.textBounds(word, 0, 0, refSize).w;
  } else {
    textFont(font || 'Georgia');
    textSize(refSize);
    textStyle(NORMAL);
    w = textWidth(word);
  }

  _runtimeCache[rtKey] = { w, refSize };

  return w * (targetSize / refSize);
}

function spaceWidthPx(fontAlias, targetSize, font) {
  textFont(font || (fontAlias === 'header' ? fontHeader : fontBody));
  textSize(targetSize);
  textStyle(NORMAL);
  textAlign(LEFT, TOP);
  return max(textWidth(' '), targetSize * 0.35);
}

function wrapParagraphToLines(paragraph, maxW, fontAlias, targetSize, font) {
  const words = paragraph.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [''];
  const spW = spaceWidthPx(fontAlias, targetSize, font);
  const lines = [];
  let lineW = 0;
  let lineWords = [];

  for (const word of words) {
    const ww = wordWidthPx(word, fontAlias, targetSize, font);
    const trial = lineWords.length > 0 ? lineW + spW + ww : ww;
    if (trial > maxW && lineWords.length > 0) {
      lines.push(lineWords.join(' '));
      lineWords = [word];
      lineW = ww;
    } else {
      lineWords.push(word);
      lineW = trial;
    }
  }
  if (lineWords.length > 0) lines.push(lineWords.join(' '));
  return lines.length ? lines : [''];
}

function wrappedLineCount(paragraph, maxW, fontAlias, targetSize, font) {
  const words = paragraph.split(/\s+/).filter(Boolean);
  if (words.length === 0) return 1;
  const spW = spaceWidthPx(fontAlias, targetSize, font);
  let lines = 1;
  let lineW = 0;
  let lineHasWord = false;

  for (const word of words) {
    const ww = wordWidthPx(word, fontAlias, targetSize, font);
    const trial = lineHasWord ? lineW + spW + ww : ww;
    if (trial > maxW && lineHasWord) {
      lines++;
      lineW = ww;
    } else {
      lineW = trial;
    }
    lineHasWord = true;
  }
  return lines;
}

function buildBodyFillText(maxW, maxH, fontAlias, targetSize, font, leading) {
  const maxLines = Math.floor(maxH / leading);
  const order = [];
  for (let i = 0; i < FILLER_SENTENCES.length; i++) order.push(i);
  shuffle(order, true);

  let resultWords = [];
  let resultLineCount = 0;
  const spW = spaceWidthPx(fontAlias, targetSize, font);
  let lastLineW = 0;

  const tryAppendSentence = (sent) => {
    const newWords = sent.split(/\s+/).filter(Boolean);
    let lines = resultLineCount || 1;
    let lw = lastLineW;
    let hasWord = resultWords.length > 0;

    for (const w of newWords) {
      const ww = wordWidthPx(w, fontAlias, targetSize, font);
      const trial = hasWord ? lw + spW + ww : ww;
      if (trial > maxW && hasWord) {
        lines++;
        lw = ww;
      } else {
        lw = trial;
      }
      hasWord = true;
    }
    if (lines > maxLines) return false;

    resultWords.push(...newWords);
    resultLineCount = lines;
    lastLineW = lw;
    return true;
  };

  let guard = 0;
  while (guard++ < 80) {
    let grew = false;
    for (const idx of order) {
      if (tryAppendSentence(FILLER_SENTENCES[idx])) grew = true;
    }
    if (!grew) break;
  }

  if (resultWords.length === 0) {
    const first = FILLER_SENTENCES[order[0]];
    const words = first.split(/\s+/).filter(Boolean);
    for (const w of words) {
      const trial = resultWords.length > 0
        ? resultWords.join(' ') + ' ' + w
        : w;
      if (wrappedLineCount(trial, maxW, fontAlias, targetSize, font) <= maxLines) {
        resultWords.push(w);
      } else {
        break;
      }
    }
  }

  return resultWords.join(' ') || '.';
}

/** Geometry for the three horizontal rule segments (matches drawDivider). */
function buildDividerSegments(innerX, divTopY, innerW, divH) {
  const cy = divTopY + divH / 2;
  const w = innerW;
  return [
    { cx: innerX + w * 0.11, cy, w: w * 0.22, h: 3, thick: true },
    { cx: innerX + w * 0.89, cy, w: w * 0.22, h: 3, thick: true },
    { cx: innerX + w * 0.5, cy, w: w * 0.52, h: 1, thick: false },
  ];
}

// ── Fuse pathfinding (grid) ─────────────────────────────────────────────

function buildObstacleGrid(columns, colAreaY, headerZones) {
  const gw = ceil(PAGE_W / FUSE_CELL);
  const gh = ceil(PAGE_H / FUSE_CELL);
  const blocked = new Uint8Array(gw * gh);

  const obs = [];

  for (const hz of headerZones) {
    obs.push(hz);
  }

  for (const col of columns) {
    let zy = colAreaY;
    for (const z of col.zones) {
      obs.push({ x: col.x, y: zy, w: col.w, h: z.h });
      zy += z.h + GUTTER_H;
    }
  }

  for (let gy = 0; gy < gh; gy++) {
    for (let gx = 0; gx < gw; gx++) {
      const wx = gx * FUSE_CELL + FUSE_CELL / 2;
      const wy = gy * FUSE_CELL + FUSE_CELL / 2;
      for (const r of obs) {
        if (wx >= r.x && wx <= r.x + r.w && wy >= r.y && wy <= r.y + r.h) {
          blocked[gy * gw + gx] = 1;
          break;
        }
      }
    }
  }

  return { gw, gh, blocked, obs };
}

function gridToWorld(gx, gy) {
  return [gx * FUSE_CELL + FUSE_CELL / 2, gy * FUSE_CELL + FUSE_CELL / 2];
}

function worldToGrid(wx, wy, gw, gh) {
  return [constrain(floor(wx / FUSE_CELL), 0, gw - 1), constrain(floor(wy / FUSE_CELL), 0, gh - 1)];
}

function nearestFreeCell(wx, wy, grid) {
  const { gw, gh, blocked } = grid;
  const [gx0, gy0] = worldToGrid(wx, wy, gw, gh);
  if (!blocked[gy0 * gw + gx0]) return [gx0, gy0];
  let best = null;
  let bestD = Infinity;
  for (let r = 1; r < max(gw, gh); r++) {
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (abs(dx) !== r && abs(dy) !== r) continue;
        const nx = gx0 + dx;
        const ny = gy0 + dy;
        if (nx < 0 || ny < 0 || nx >= gw || ny >= gh) continue;
        if (blocked[ny * gw + nx]) continue;
        const d = dx * dx + dy * dy;
        if (d < bestD) {
          bestD = d;
          best = [nx, ny];
        }
      }
    }
    if (best) return best;
  }
  return null;
}

function bfsPath(grid, sx, sy, gx, gy) {
  const { gw, gh, blocked } = grid;
  const sz = gw * gh;
  const prev = new Int32Array(sz).fill(-1);
  const visited = new Uint8Array(sz);
  const sIdx = sy * gw + sx;
  const gIdx = gy * gw + gx;
  visited[sIdx] = 1;
  const q = [sx, sy];
  let head = 0;

  while (head < q.length) {
    const cx = q[head++];
    const cy = q[head++];
    const ci = cy * gw + cx;
    if (ci === gIdx) {
      const path = [];
      let i = gIdx;
      while (i !== -1 && i !== sIdx) {
        path.push(gridToWorld(i % gw, floor(i / gw)));
        i = prev[i];
      }
      path.push(gridToWorld(sx, sy));
      path.reverse();
      return path;
    }
    const neighbors = [
      [cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1],
    ];
    for (const [nx, ny] of neighbors) {
      if (nx < 0 || ny < 0 || nx >= gw || ny >= gh) continue;
      const ni = ny * gw + nx;
      if (visited[ni] || blocked[ni]) continue;
      visited[ni] = 1;
      prev[ni] = ci;
      q.push(nx, ny);
    }
  }
  return null;
}

function simplifyPath(pts) {
  if (!pts || pts.length < 3) return pts || [];
  const out = [pts[0]];
  for (let i = 1; i < pts.length - 1; i++) {
    const [x0, y0] = out[out.length - 1];
    const [x1, y1] = pts[i];
    const [x2, y2] = pts[i + 1];
    if ((x0 === x1 && x1 === x2) || (y0 === y1 && y1 === y2)) continue;
    out.push(pts[i]);
  }
  out.push(pts[pts.length - 1]);
  return out;
}

function pickRandomEdgeStart(grid) {
  const { gw, gh, blocked } = grid;
  const candidates = [];
  for (let gx = 0; gx < gw; gx++) {
    if (!blocked[gx]) candidates.push([gx, 0]);
    if (!blocked[(gh - 1) * gw + gx]) candidates.push([gx, gh - 1]);
  }
  for (let gy = 1; gy < gh - 1; gy++) {
    if (!blocked[gy * gw]) candidates.push([0, gy]);
    if (!blocked[gy * gw + gw - 1]) candidates.push([gw - 1, gy]);
  }
  if (candidates.length === 0) return null;
  return candidates[floor(random(candidates.length))];
}

function generateWaypoints(grid, fuseTarget, numWaypoints) {
  const { gw, gh, blocked } = grid;
  const endCx = fuseTarget.x + fuseTarget.w / 2;
  const endCy = fuseTarget.y + fuseTarget.h / 2;
  const waypoints = [];

  for (let i = 0; i < numWaypoints; i++) {
    let bestCell = null;
    let bestScore = -Infinity;

    for (let attempt = 0; attempt < FUSE_WAYPOINT_TRIES; attempt++) {
      const wx = random(MARGIN, PAGE_W - MARGIN);
      const wy = random(MARGIN, PAGE_H - MARGIN);
      const [gx, gy] = worldToGrid(wx, wy, gw, gh);
      if (blocked[gy * gw + gx]) continue;

      let minDistToExisting = Infinity;
      for (const [ex, ey] of waypoints) {
        const d = Math.hypot(wx - ex, wy - ey);
        if (d < minDistToExisting) minDistToExisting = d;
      }
      if (waypoints.length === 0) minDistToExisting = 200;

      const distToEnd = Math.hypot(wx - endCx, wy - endCy);
      const spread = minDistToExisting;
      const notTooClose = distToEnd > 60 ? 1 : 0;
      const score = spread * 0.7 + distToEnd * 0.15 + random(80) * notTooClose;

      if (score > bestScore) {
        bestScore = score;
        bestCell = [wx, wy];
      }
    }

    if (bestCell) waypoints.push(bestCell);
  }

  return waypoints;
}

function computeFusePath(columns, colAreaY, fuseTarget, headerZones) {
  const grid = buildObstacleGrid(columns, colAreaY, headerZones);

  const endWx = fuseTarget.x + fuseTarget.w / 2;
  const endWy = fuseTarget.y + fuseTarget.h / 2;

  const startCell = pickRandomEdgeStart(grid);
  const endCell = nearestFreeCell(endWx, endWy, grid);
  if (!startCell || !endCell) return fallbackFusePath(fuseTarget);

  const waypoints = generateWaypoints(grid, fuseTarget, FUSE_WAYPOINTS);

  const worldWaypoints = waypoints.map(([wx, wy]) => {
    const cell = nearestFreeCell(wx, wy, grid);
    return cell;
  }).filter(Boolean);

  const chain = [startCell, ...worldWaypoints, endCell];
  let fullPath = [];

  for (let i = 0; i < chain.length - 1; i++) {
    const [ax, ay] = chain[i];
    const [bx, by] = chain[i + 1];
    const segment = bfsPath(grid, ax, ay, bx, by);
    if (!segment || segment.length < 2) continue;
    if (fullPath.length > 0) segment.shift();
    fullPath.push(...segment);
  }

  if (fullPath.length < 2) return fallbackFusePath(fuseTarget);

  fullPath = simplifyPath(fullPath);

  const last = fullPath[fullPath.length - 1];
  if (Math.hypot(last[0] - endWx, last[1] - endWy) > FUSE_CELL * 2) {
    fullPath.push([endWx, endWy]);
  } else {
    fullPath[fullPath.length - 1] = [endWx, endWy];
  }

  return simplifyPath(fullPath);
}

function fallbackFusePath(fuseTarget) {
  const innerX = MARGIN;
  const innerY = MARGIN;
  const innerBottom = innerY + (PAGE_H - MARGIN * 2);
  const startX = innerX + 18;
  const startY = innerBottom - 28;
  const endX = fuseTarget.x + fuseTarget.w / 2;
  const endY = fuseTarget.y + fuseTarget.h / 2;
  const midY = innerY + 120;
  const elbowX = fuseTarget.x - 50;
  return simplifyPath([
    [startX, startY],
    [startX, midY],
    [elbowX, midY],
    [elbowX, endY],
    [endX, endY],
  ]);
}

function pickHeaderCopy() {
  return {
    mastTitle: random(NEWSPAPER_TITLES),
    mastSub: random(SUBTEXT_LINES),
    kicker: random(KICKER_LINES),
    banner: random(BANNER_HEADLINES),
    secondary: random(SECONDARY_HEADERS),
  };
}


